shell_commands:
/bin/zsh -lc "cat > src/orchestration/tools/registry.paths.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#4
it('reports a wrong type with its property path and no input value', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
    async () => 'forecast'
  );
  const response = await registry.execute('weather', {location: 123456789});
  expect({result: response.result, leaked: response.result.includes('123456789')}).toEqual({
    result: expect.stringMatching(/location.*string/),
    leaked: false,
  });
});
EOF
python3 - <<'PY'
p='specs/hal-engine-tool-input-validation/spec.md'
s=open(p).read().replace('- When "'`input` satisfies'"', '- A wrong-typed property is reported by path and expected type without including its value ([validated by: reports a wrong type with its property path and no input value](../../src/orchestration/tools/registry.paths.test.ts#L4)).\\n- When "'`input` satisfies'"')
open(p,'w').write(s)
PY
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.paths.test.ts"
